                                    assignmentTarget={assignmentTarget}
                                    bindingStore={bindingStore}
                                    primaryPath={primaryPath}
                                    sequenceCardInternalId={baseContext.kind === 'card' ? baseContext.cardInternalId ?? null : null}
                                />
                            ) : null}
